import{_ as l,l as i,o as e,c as n,v as t,p as s,x as o,d as p,i as A,S as d}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"SABR 对 LMM 校准","description":"","frontmatter":{"title":"SABR 对 LMM 校准","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/sabr-lmm-calib.md","filePath":"quant/sabr-lmm-calib.md","lastUpdated":1789023840000}'),m={name:"quant/sabr-lmm-calib.md"};function M(h,a,B,c,u,b){const r=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="sabr-对-lmm-校准" tabindex="-1">SABR 对 LMM 校准 <a class="header-anchor" href="#sabr-对-lmm-校准" aria-label="Permalink to &quot;SABR 对 LMM 校准&quot;">​</a></h1><div class="epigraph"><p>每个 swaption 格子一个 SABR，只保证该格子的微笑；LMM 要的是整条远期曲线的动态同时重现这些微笑，而不能破坏远期之间的相关。</p><footer>—— Hagan, Kumar, Lesniewski and Woodward, Managing Smile Risk, Wilmott, 2002；Rebonato 对 LMM 校准的论述</footer></div><p><a href="/quant/caps-floors-swaptions">上一课</a>给出 cap 与 swaption 两张网。主干 <a href="/quant/sabr">SABR</a> 与 <a href="/quant/sabr-calib">SABR 校准</a>、<a href="/quant/lmm">LMM</a> 已分写。缺口是<strong>把微笑装进 LMM</strong>：不是再推 SABR 公式，而是期限结构模型如何吸收按格子校准的 \\(\\alpha,\\rho,\\nu\\)，以及为什么「每个互换一个 SABR」加不起来等于一个无套利 LMM。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>市场习惯：对每个 \\((T_{\\mathrm{exp}},T_{\\mathrm{tenor}})\\) 的 swaption 拟合 SABR，得到该互换率的微笑。LMM 的状态是一向量远期 \\(L_i\\)，瞬时协方差决定所有互换率的动态。问题是过度识别：格子数目远大于合理的因子数，精确重现所有 SABR 微笑会破坏无套利或把远期 vol 变成不稳定的尖刺。校准必须正则化——与 <a href="/quant/calibration-regularization">校准正则化</a> 同一逻辑，对象换成远期 vol 曲线与相关结构。</p><p>Rebonato 的近似：互换率波动是远期波动的加权，权重冻结。于是可以把 SABR 的 ATM \\(\\alpha\\) 映射成 LMM 的瞬时 vol 函数，再尽量拟合 \\(\\rho,\\nu\\) 到因子的随机波动或位移。不能把每个格子的 \\(\\nu\\) 都当独立状态。</p><h3 id="相关结构是第一约束" tabindex="-1">相关结构是第一约束 <a class="header-anchor" href="#相关结构是第一约束" aria-label="Permalink to &quot;相关结构是第一约束&quot;">​</a></h3><p>LMM 的因子相关决定曲线形态风险（与 cap/swaption 的差）。若为了拟合翼部而让远期 vol 乱跳，相关校准会跟着重拟合噪声。顺序应是：先因子数与相关（PCA 式的曲线因子），再 ATM vol 期限结构，再微笑（SABR \\(\\rho,\\nu\\) 或随机 vol 层），每层带隔日罚。</p><p><span class="marginnote">SABR 的 \\(\\beta\\) 在利率里常取 0.5 或 0，与负利率移位耦合。\\(\\beta\\) 与移位不要同时自由，否则识别崩溃。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>(1) 用历史或隐含 PCA 定 LMM 因子数与相关。(2) 用 swaption ATM 校准时间依赖的远期 vol，Rebonato 权重。(3) 用 SABR 微笑校准随机 vol 或局部位移参数，只保留少量期限依赖。(4) 检查 caplet 剥离是否在容差内，否则加 cap 权重或承认模型带。(5) 全局搜索只在低维层，局部 LM 在 vol 曲线层，见 <a href="/quant/calibration-global-opt">全局优化</a>。</p><p>对冲仍用市场 SABR 桶（按格子），模型内的远期 vol 敏感度要映回格子，否则交易员无法下单。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>SABR 是单标的微笑的局部参数化；LMM 是曲线的无套利动态。前者是报价坐标，后者是状态变量。校准是从坐标到状态的反问题，不适定。正则化等于承认曲线只有少数因子，微笑的 \\(\\nu\\) 是加在因子上的一层，而不是每个格子一个随机源。</p>',14)),(e(),s(d,null,{default:o(()=>[A(r,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20Grid%5B%22Swaption%20%E6%A0%BC%E5%AD%90%20SABR%22%5D%20--%3E%20ATM%5B%22ATM%20%E6%98%A0%E5%B0%84%E5%88%B0%E8%BF%9C%E6%9C%9F%20vol%22%5D%0A%20%20PCA%5B%22%E6%9B%B2%E7%BA%BF%E5%9B%A0%E5%AD%90%E7%9B%B8%E5%85%B3%22%5D%20--%3E%20LMM%5B%22LMM%20%E7%8A%B6%E6%80%81%22%5D%0A%20%20ATM%20--%3E%20LMM%0A%20%20Smile%5B%22%E5%B0%91%E9%87%8F%20%CF%81%20%CE%BD%20%E5%B1%82%22%5D%20--%3E%20LMM%0A%20%20LMM%20--%3E%20Check%5B%22%E5%9B%9E%E6%A3%80%20cap%20%E4%B8%8E%E6%97%A0%E5%A5%97%E5%88%A9%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>精确拟合所有翼部会导致明天校准崩溃。现金交割 swaption、RFR 复合与历史 Libor SABR 网格不兼容。模型风险：换因子数比微调某格子 \\(\\nu\\) 对账面影响更大，应进 Cont 区间。本课不发明新的 arXiv 校准算法。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>格子 SABR 是报价；LMM 是无套利动态；二者校准是正则化反问题。</li><li>先相关与 ATM，再少量微笑参数；对冲映回格子。</li><li>\\(\\beta\\) 与移位不要同时自由识别。</li><li>出处：Hagan et al., <em>Wilmott</em>, 2002；Rebonato, <em>Modern Pricing of Interest-Rate Derivatives</em>。</li></ul>',4))])}const S=l(m,[["render",M]]);export{_ as __pageData,S as default};
